import React, { useEffect, useRef, useState } from 'react';
import mapboxgl from 'mapbox-gl';
import 'mapbox-gl/dist/mapbox-gl.css';

// Set Mapbox access token
mapboxgl.accessToken = 'pk.eyJ1IjoiYXZlcnljb3RlIiwiYSI6ImNtZXhsZXB6NzBtNWgybG9lZ3ppYmthcDcifQ.8CEbNWYb5Gnts1NjV6RrTQ';

const MapDebug = () => {
  const mapContainer = useRef(null);
  const map = useRef(null);
  const [status, setStatus] = useState('Initializing...');
  const [error, setError] = useState(null);
  const [debugInfo, setDebugInfo] = useState({});

  useEffect(() => {
    if (map.current) return;

    const initializeMap = async () => {
      try {
        setStatus('Creating map instance...');
        console.log('MapDebug: Starting map initialization');

        // Collect debug information
        const info = {
          mapboxgl: typeof mapboxgl,
          accessToken: mapboxgl.accessToken ? 'Set' : 'Missing',
          container: mapContainer.current ? 'Found' : 'Missing',
          containerWidth: mapContainer.current?.offsetWidth || 0,
          containerHeight: mapContainer.current?.offsetHeight || 0,
          userAgent: navigator.userAgent,
          online: navigator.onLine,
          timestamp: new Date().toISOString()
        };

        setDebugInfo(info);
        console.log('MapDebug: Debug info:', info);

        // Test if Mapbox is available
        if (!mapboxgl) {
          throw new Error('Mapbox GL JS is not loaded');
        }

        // Test access token
        if (!mapboxgl.accessToken) {
          throw new Error('Mapbox access token is not set');
        }

        setStatus('Loading map tiles...');

        // Use Mapbox tiles with your personal token
        map.current = new mapboxgl.Map({
          container: mapContainer.current,
          style: 'mapbox://styles/mapbox/streets-v12',
          center: [-63.5756, 44.6475], // Halifax
          zoom: 12,
          // Minimal configuration for testing
          preserveDrawingBuffer: false,
          antialias: false,
          attributionControl: true
        });

        map.current.on('load', () => {
          setStatus('Map loaded successfully!');
          console.log('MapDebug: Map loaded successfully');
          setDebugInfo(prev => ({
            ...prev,
            mapLoaded: true,
            mapStyle: map.current.getStyle().name || 'Unknown'
          }));
        });

        map.current.on('error', (e) => {
          console.error('MapDebug: Map error:', e);
          setError(`Map error: ${e.error?.message || 'Unknown error'}`);
          setStatus('Map failed to load');
        });

        map.current.on('styledata', () => {
          console.log('MapDebug: Map style loaded');
        });

        map.current.on('sourcedata', (e) => {
          console.log('MapDebug: Source data event:', e);
        });

      } catch (err) {
        console.error('MapDebug: Failed to initialize map:', err);
        setError(`Initialization error: ${err.message}`);
        setStatus('Failed to initialize');
      }
    };

    initializeMap();

    return () => {
      if (map.current) {
        map.current.remove();
        map.current = null;
      }
    };
  }, []);

  return (
    <div style={{ 
      position: 'relative', 
      width: '100%', 
      height: '100vh',
      border: '2px solid #ccc'
    }}>
      <div 
        ref={mapContainer} 
        style={{ 
          width: '100%', 
          height: '100%' 
        }} 
      />

      {/* Debug overlay */}
      <div style={{
        position: 'absolute',
        top: '10px',
        left: '10px',
        background: 'rgba(0, 0, 0, 0.9)',
        color: 'white',
        padding: '15px',
        borderRadius: '5px',
        fontFamily: 'monospace',
        fontSize: '12px',
        zIndex: 1000,
        maxWidth: '400px',
        maxHeight: '80vh',
        overflow: 'auto'
      }}>
        <h3 style={{ margin: '0 0 10px 0', color: '#3498db' }}>Map Debug Info</h3>

        <div><strong>Status:</strong> {status}</div>

        {error && (
          <div style={{ color: '#ff6b6b', marginTop: '5px' }}>
            <strong>Error:</strong> {error}
          </div>
        )}

        <div style={{ marginTop: '10px' }}>
          <strong>Debug Information:</strong>
          <pre style={{ fontSize: '10px', marginTop: '5px' }}>
            {JSON.stringify(debugInfo, null, 2)}
          </pre>
        </div>

        <div style={{ marginTop: '10px' }}>
          <strong>Network Test:</strong>
          <button 
            onClick={async () => {
              try {
                console.log('Testing Mapbox connectivity...');
                const response = await fetch('https://api.mapbox.com/mapbox-gl-js/v2.15.0/mapbox-gl.css');
                console.log('Network test result:', response.status);
                alert(`Network test: ${response.status === 200 ? 'SUCCESS' : 'FAILED'} (${response.status})`);
              } catch (err) {
                console.error('Network test failed:', err);
                alert(`Network test: FAILED - ${err.message}`);
              }
            }}
            style={{
              background: '#3498db',
              color: 'white',
              border: 'none',
              padding: '5px 10px',
              borderRadius: '3px',
              cursor: 'pointer',
              marginTop: '5px'
            }}
          >
            Test Network
          </button>
          <button 
            onClick={async () => {
              try {
                console.log('Testing Mapbox token...');
                const token = mapboxgl.accessToken;
                const response = await fetch(`https://api.mapbox.com/geocoding/v5/mapbox.places/Halifax.json?access_token=${token}&limit=1`);
                const data = await response.json();
                console.log('Token test result:', response.status, data);
                if (response.status === 200 && data.features) {
                  alert(`Token test: SUCCESS - Token is valid`);
                } else {
                  alert(`Token test: FAILED - ${response.status}`);
                }
              } catch (err) {
                console.error('Token test failed:', err);
                alert(`Token test: FAILED - ${err.message}`);
              }
            }}
            style={{
              background: '#e74c3c',
              color: 'white',
              border: 'none',
              padding: '5px 10px',
              borderRadius: '3px',
              cursor: 'pointer',
              marginTop: '5px',
              marginLeft: '5px'
            }}
          >
            Test Token
          </button>
        </div>
      </div>

      {/* Test controls */}
      <div style={{
        position: 'absolute',
        top: '10px',
        right: '10px',
        background: 'rgba(0, 0, 0, 0.8)',
        color: 'white',
        padding: '10px',
        borderRadius: '5px',
        zIndex: 1000
      }}>
        <button 
          onClick={() => window.location.reload()}
          style={{
            background: '#3498db',
            color: 'white',
            border: 'none',
            padding: '5px 10px',
            borderRadius: '3px',
            cursor: 'pointer',
            marginRight: '5px'
          }}
        >
          Reload
        </button>
        <button 
          onClick={() => {
            if (map.current) {
              console.log('Map instance:', map.current);
              console.log('Map style:', map.current.getStyle());
              console.log('Map loaded:', map.current.isStyleLoaded());
              alert('Check console for map debug info');
            } else {
              alert('No map instance available');
            }
          }}
          style={{
            background: '#e74c3c',
            color: 'white',
            border: 'none',
            padding: '5px 10px',
            borderRadius: '3px',
            cursor: 'pointer'
          }}
        >
          Debug
        </button>
      </div>
    </div>
  );
};

export default MapDebug;
